{
  "findings": [
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that strangers can email their child through Google Classroom announcements, which can be turned off by the administrator.",
      "stance": "risk",
      "quote": "Your kid will receive an email when the teacher posts an announcement. These emails come through your kid's email account, not in Classroom."
    },
    {
      "ref": "[D521]",
      "area": "money",
      "claim": "A parent reports that Google Classroom does not push in-app purchases, loot boxes, or pay-to-win features.",
      "stance": "neutral",
      "quote": "Google Classroom is just one part of Google's Workspace for Education, and some of the apps, including third-party programs, can be tracked."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "A parent reports that Google may collect data when additional services like YouTube and Maps are enabled, but education accounts cannot be tracked or mined for data beyond what is necessary for educational purposes.",
      "stance": "mitigation",
      "quote": "Logging in with a school account, rather than a personal Gmail account, protects kids from some data collection because education accounts can't be tracked or mined for data (beyond what's necessary for educational purposes)."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, as the platform is designed for school use and requires a school account, which inherently restricts younger children.",
      "stance": "neutral",
      "quote": "Google Classroom is just one part of Google's Workspace for Education, and some of the apps, including third-party programs, can be tracked."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that reviewers have not identified any inappropriate content in Google Classroom itself, though third‑party apps like YouTube may contain mature material if not restricted.",
      "stance": "neutral",
      "quote": "If your kid has YouTube enabled in their Classroom account, you'll need to speak to the admin, not the teacher, if you don't want your kid watching YouTube (the admin can also enable \"restricted mode\" for YouTube, which limits some mature content)."
    },
    {
      "ref": "[D521]",
      "area": "developer_record",
      "claim": "A parent reports that there are no known fines, breaches, lawsuits, or regulatory actions against Google related to Google Classroom.",
      "stance": "neutral",
      "quote": "Google doesn't share or sell student data to partners, and it vets the developers it uses for Classroom, those third parties could collect information from your kid, then profile and target them using that data."
    }
  ]
}
